export const serviceBySlug = Object.fromEntries(services.map((service) => [service.slug, service]));

const A = (slug, label, region, context, propertyMix, plumbingContext, access) => ({ slug, label, region, h1: `Plumber in ${label}, TX`, keyword: `plumber ${label} TX`, context, propertyMix, plumbingContext, access });

export const areas = [
  A("houston","Houston","Houston core","Houston stretches across bayou corridors, freeway loops, dense urban districts, and lower-density residential areas, so a ZIP code and neighborhood are essential routing details.","The city includes early-20th-century homes, postwar subdivisions, high-rise buildings, townhomes, apartments, warehouses, and new infill construction.","Pipe age, foundation type, municipal-service boundaries, flood history, and long cooling seasons can change the likely access and repair path.","I-10, I-45, US-59/I-69, Loop 610, and Beltway 8 shape arrival planning; parking, loading, gates, and building access should be confirmed."),
  A("downtown-houston","Downtown Houston","Houston core","Downtown is a compact business and residential district framed by elevated freeways, METRORail streets, and the Buffalo Bayou edge.","High-rises, converted historic buildings, hotels, entertainment venues, and civic facilities place many plumbing components in shared shafts and managed spaces.","Vertical risers, pressure zones, commercial restrooms, booster equipment, and tenant shutdown notices often matter more than a simple curbside arrival.","Loading docks, garage clearances, security check-in, freight elevators, and street closures should be arranged before dispatch."),
  A("midtown-houston","Midtown Houston","Houston core","Midtown sits between Downtown and the Museum District with rail corridors, dense blocks, nightlife, and rapid residential redevelopment.","Older small buildings share the area with apartments, townhomes, restaurants, and mixed-use projects, producing varied pipe materials and access points.","Fixture demand, shared building drains, restaurant connections, and remodel transitions can create problems that cross individual units.","Limited curb space, gated garages, and weekend or event traffic make unit number, parking instructions, and management contacts useful."),
  A("montrose","Montrose","Houston core","Montrose is an inner-loop area of shaded residential streets, commercial corridors, older bungalows, apartments, and substantial infill.","Pier-and-beam homes, renovated houses, duplexes, townhomes, and multifamily buildings can place piping in crawl spaces, walls, slabs, or mixed remodel routes.","A repair may need to distinguish original galvanized or cast-iron sections from newer copper, PVC, or PEX added during renovations.","Narrow drives, mature landscaping, shared parking, and tenant access can affect equipment placement and exterior sewer work."),
  A("houston-heights","Houston Heights","Houston core","The Heights combines a historic street grid and bungalow fabric with dense new construction near commercial corridors and bayou-adjacent areas.","Pier-and-beam houses, cottages, townhomes, garage apartments, and updated commercial buildings create very different underfloor and wall access conditions.","Older service lines, remodel tie-ins, shallow yard utilities, and newer high-demand fixtures deserve separate evaluation rather than age-based assumptions.","Alley access, narrow lots, preservation-sensitive finishes, and busy streets around Heights Boulevard and 19th Street should be noted."),
  A("river-oaks","River Oaks","Houston core","River Oaks includes large landscaped lots, winding residential streets, and nearby commercial districts between Downtown and Uptown.","Estates range from older masonry homes to extensively renovated and newly built properties with complex mechanical rooms and multiple water-heating zones.","Long pipe runs, recirculation systems, specialty fixtures, irrigation connections, and concealed shutoffs require careful system mapping.","Gate instructions, protected finishes, contractor entrances, and coordination with property staff should be established in advance."),
  A("west-university-place","West University Place","Houston core","West University Place is a compact incorporated city inside the Houston urban core, close to Rice University, the Medical Center, and major employment districts.","Older cottages, expanded homes, teardown replacements, and narrow-lot construction can create layered plumbing histories within a small footprint.","Sewer routing, slab versus pier access, high fixture counts, and remodel connections should be checked against the actual property rather than neighborhood age alone.","Tight streets, school traffic, small side yards, and municipal permitting boundaries can shape scheduling and excavation."),
  A("bellaire","Bellaire","Houston core","Bellaire is an incorporated inner-loop community crossed by major roads and drainage channels, with residential blocks and a compact commercial core.","Housing includes mid-century homes, raised or rebuilt properties, large new residences, schools, and local businesses.","Foundation elevation, post-storm rebuilding, older buried services, and high-capacity modern plumbing systems create distinct diagnostic paths.","Verify the City of Bellaire jurisdiction, driveway access, drainage easements, and any need to protect finished landscaping."),
  A("memorial","Memorial","Houston core","The Memorial area extends along wooded neighborhoods and commercial centers west of Loop 610, with Buffalo Bayou and tributaries influencing the landscape.","Large older homes, renovated properties, townhomes, apartments, and newer construction may have long service runs and heavily landscaped yards.","Slab routes, sewer depth, tree-root interaction, pressure regulation, and equipment located in attics or remote mechanical rooms are common planning considerations.","Beltway 8 and I-10 congestion, gated subdivisions, private streets, and flood-recovery construction can affect dispatch."),
  A("spring-branch","Spring Branch","Houston core","Spring Branch covers a broad west-central area north of I-10 with established subdivisions, industrial pockets, apartments, and active infill.","Postwar slab homes, ranch houses, townhomes, warehouses, and new compact developments produce mixed service-line ages and drain layouts.","Galvanized supply remnants, cast-iron drains, slab leaks, pressure issues, and remodel tie-ins may appear, but each property needs confirmation.","Large area boundaries make the exact ZIP code and cross streets essential; construction and rail crossings can affect local routes."),
  A("uptown-galleria","Uptown and the Galleria","Houston core","Uptown is a dense commercial and residential district centered on the Galleria and Post Oak Boulevard west of Loop 610.","Office towers, hotels, retail, condominiums, apartments, and high-end residential buildings rely on managed vertical systems and scheduled access.","Shared stacks, pressure zones, commercial kitchens, public restrooms, and tenant improvements often require building-engineer coordination.","Parking decks, loading docks, security, freight elevators, and peak traffic on Westheimer and the West Loop should be planned."),
  A("meyerland","Meyerland","Houston core","Meyerland lies southwest of the urban core near Brays Bayou, with established residential streets and major retail corridors.","Mid-century ranch houses, rebuilt elevated homes, apartments, and retail properties can differ sharply in foundation and utility configuration.","Older under-slab drainage, flood-related renovations, rerouted supply piping, and cleanout access should be documented property by property.","Bayou crossings, school traffic, construction, and limited side-yard access can influence sewer inspection and excavation."),
  A("braeswood-place","Braeswood Place","Houston core","Braeswood Place is a residential community along the Brays Bayou corridor near the Texas Medical Center and inner-loop employment centers.","Original ranch homes, expanded houses, and newer replacements create a mix of slab systems, relocated kitchens, and high-demand additions.","Drainage age, under-slab routing, flood-repair history, and water-heater placement can materially affect scope.","Medical Center traffic, bayou bridges, narrow side setbacks, and occupied-home protection should be included in arrival planning."),
  A("eado","East Downtown Houston","Houston core","East Downtown, commonly called EaDo, sits just east of Downtown among stadiums, rail lines, warehouses, townhomes, and entertainment uses.","Converted industrial buildings, new multifamily projects, bars, restaurants, and narrow-lot homes combine commercial and residential plumbing demands.","Older large-diameter drains, grease-bearing waste, shared utility rooms, and new connections to legacy infrastructure can complicate diagnosis.","Events, rail crossings, gated developments, loading access, and limited street parking should be confirmed before service."),
  A("third-ward","Third Ward","Houston core","Third Ward is a historic inner-city community southeast of Downtown near universities, transit, and the Texas Medical Center.","Older wood-frame homes, small multifamily buildings, churches, institutions, and newer townhomes may have varied foundations and utility histories.","Underfloor access, aging service lines, remodel additions, sewer cleanout availability, and landlord authorization can influence the work plan.","Campus activity, rail corridors, narrow lots, and tenant communication should be considered when scheduling."),
  A("energy-corridor","Energy Corridor","Houston core","The Energy Corridor follows the I-10 west corridor near major office campuses, reservoirs, bayous, apartments, and established neighborhoods.","Corporate facilities, hotels, multifamily properties, retail, and large homes create both high-occupancy commercial and residential service needs.","Building shutdowns, backflow devices, commercial water heating, slab routing, and flood-related system changes may require different specialists.","I-10 traffic, secured campuses, parking structures, and reservoir-adjacent road conditions can affect response logistics."),
  A("the-woodlands","The Woodlands","North Houston","The Woodlands is a master-planned community north of Houston organized around wooded villages, commercial centers, and major corridors near I-45.","Single-family homes, townhomes, apartments, offices, retail, medical facilities, and hospitality properties span multiple development eras.","Mature trees, long buried services, slab construction, whole-home filtration, and multi-water-heater layouts can influence diagnosis and access.","Village name, gate information, exact municipal or utility district, and routes from I-45 or Grand Parkway should be supplied."),
  A("spring","Spring","North Houston","Spring covers a large, loosely defined area north of Houston across Harris and Montgomery County communities.","Established subdivisions, newer master-planned neighborhoods, apartments, retail strips, and semi-rural tracts produce widely different plumbing systems.","Utility district boundaries, private septic in some outlying properties, slab leaks, tree roots, and water-pressure differences require address-level verification.","Because 'Spring' spans many ZIP codes, the subdivision, nearest major road, and county should be confirmed before routing."),
  A("tomball","Tomball","North Houston","Tomball combines a historic city center, suburban subdivisions, commercial growth, and rural-edge properties northwest of Houston.","Older in-town homes, acreage properties, new neighborhoods, medical buildings, restaurants, and light industrial sites may use municipal or private systems.","Well or septic interfaces, long service runs, grease systems, buried gas, and new-construction warranty boundaries can alter the correct provider match.","SH 249, Grand Parkway, rail crossings, acreage gates, and city-versus-county jurisdiction should be included in scheduling details."),
  A("humble","Humble","North Houston","Humble sits northeast of Houston near I-69, Bush Intercontinental Airport, and the Lake Houston area.","Established homes, apartment communities, hotels, restaurants, retail, and airport-support businesses create a broad range of fixture and drainage demand.","Commercial occupancy, slab piping, older sewer segments, high-use water heaters, and utility district boundaries can affect scope.","Airport traffic, I-69 congestion, gated complexes, and commercial receiving hours should be checked before dispatch."),
  A("kingwood","Kingwood","North Houston","Kingwood is a wooded, village-based community along the Lake Houston and San Jacinto River area northeast of central Houston.","Planned subdivisions, large homes, townhomes, apartments, schools, and retail areas often sit among mature trees and drainage corridors.","Root intrusion, long yard sewer runs, slab routes, pool-house or outdoor connections, and flood-repair history may be relevant to individual properties.","Village identification, bridge routes, gated sections, and weather effects near river corridors help refine access planning."),
  A("atascocita","Atascocita","North Houston","Atascocita is a large suburban community east of Humble near Lake Houston, FM 1960, and several master-planned neighborhoods.","Homes from multiple building cycles, golf-course communities, apartments, schools, and retail centers create varied fixture and service layouts.","Slab leaks, pressure regulation, long exterior services, irrigation backflow, and water-heater capacity are common decision categories rather than assumed defects.","FM 1960 congestion, neighborhood gates, lake-area routes, and utility district identification should be included with a request."),
  A("cypress","Cypress","North Houston","Cypress spans a wide northwest Houston area along US 290 and Grand Parkway with master-planned communities and older rural remnants.","Newer subdivisions, acreage homes, apartments, schools, retail, and commercial campuses may rely on different municipal utility districts.","High fixture counts, whole-house treatment, irrigation backflow, builder warranty questions, and occasional private-system interfaces need property-specific review.","Subdivision, ZIP code, MUD, gate access, and construction along US 290 or Grand Parkway are important routing details."),
  A("katy","Katy","West and southwest","Katy includes the incorporated city and a much larger west-Houston mailing area across Harris, Fort Bend, and Waller counties.","Historic in-town homes, master-planned subdivisions, apartments, schools, restaurants, warehouses, and new construction span very different utilities.","Municipal versus MUD service, slab piping, water treatment, irrigation backflow, and builder responsibility should be verified by exact address.","County, subdivision, and ZIP code matter because 'Katy' is extensive; I-10 and Grand Parkway traffic also shape dispatch."),
  A("cinco-ranch","Cinco Ranch","West and southwest","Cinco Ranch is a large master-planned community in the Katy area organized around villages, lakes, schools, and retail corridors.","Primarily planned single-family neighborhoods are joined by apartments, townhomes, offices, and shopping areas built over several decades.","Manifold plumbing, water-heater combinations, whole-house treatment, irrigation devices, and high-demand fixtures may require model- and phase-specific information.","Village, gate instructions, MUD, and access from Grand Parkway, Westpark Tollway, or local boulevards should be noted."),
  A("fulshear","Fulshear","West and southwest","Fulshear is a fast-growing city west of Houston where historic rural patterns meet large new master-planned developments.","New subdivisions, custom acreage homes, small commercial centers, and remaining rural properties may use municipal, district, well, or septic arrangements.","Long service lines, pressure regulation, water treatment, septic handoffs, and new-build warranty coverage should be resolved before work.","FM 1093, winding rural roads, gated communities, construction traffic, and Fort Bend County jurisdiction affect access."),
  A("richmond","Richmond","West and southwest","Richmond is a Fort Bend County city along the Brazos River with a historic core, suburban development, government facilities, and nearby master-planned communities.","Older in-town buildings, postwar homes, new subdivisions, apartments, restaurants, and institutional properties span many plumbing eras.","Legacy sewers, tree roots, flood history, private-system edges, and modern high-demand installations create distinct diagnostic needs.","Brazos crossings, city limits, county facilities, rail lines, and US 90A traffic should be considered in dispatch planning."),
  A("rosenberg","Rosenberg","West and southwest","Rosenberg is a growing Fort Bend County city southwest of Houston with a historic rail-centered core, established neighborhoods, and expanding suburbs.","Older homes and storefronts coexist with new subdivisions, schools, industrial facilities, restaurants, and acreage-edge properties.","Sewer access, pipe age, commercial grease systems, private utility interfaces, and storm-related repairs can require different equipment and credentials.","US 59/I-69, rail crossings, city-versus-county location, and construction near new developments should be included with the request."),
  A("sugar-land","Sugar Land","West and southwest","Sugar Land is a Fort Bend County city of planned neighborhoods, corporate campuses, retail centers, and established communities southwest of Houston.","Single-family homes, townhomes, apartments, offices, medical facilities, restaurants, and civic buildings produce mixed residential and commercial demand.","Slab routing, mature-tree sewer impacts, backflow requirements, commercial shutdowns, and water-treatment equipment may affect planning.","Subdivision access, city jurisdiction, US 59/I-69 traffic, and managed commercial properties should be identified early."),
  A("stafford","Stafford","West and southwest","Stafford is a compact city southwest of Houston with residential neighborhoods, business parks, warehouses, retail, and light industry.","Homes, apartments, restaurants, offices, manufacturing spaces, and distribution buildings create varied pipe sizes and occupancy requirements.","Commercial backflow, process connections, high-use restrooms, grease waste, and building shutdown coordination can be central to the scope.","City boundaries, loading access, US 90A rail crossings, and business operating hours should accompany a service request."),
  A("missouri-city","Missouri City","West and southwest","Missouri City spans Fort Bend and Harris County areas with established planned neighborhoods, newer development, and commercial corridors.","Homes range from older subdivisions to large newer properties, with apartments, schools, retail, and institutional facilities throughout.","Utility district boundaries, slab piping, sewer roots, irrigation backflow, and water-pressure regulation vary by neighborhood and construction era.","Exact city, county, subdivision, gate, and route from Fort Bend Parkway, Highway 6, or US 90A help avoid dispatch ambiguity."),
  A("pearland","Pearland","South and southeast","Pearland is a large Brazoria County city south of Houston spanning older town areas, master-planned communities, and major retail corridors.","Established homes, new subdivisions, apartments, medical facilities, restaurants, and commercial development create diverse plumbing loads.","Municipal and district boundaries, slab piping, long services, water treatment, and new-construction responsibility require address-level confirmation.","Broad east-west travel, SH 288 traffic, construction, subdivision gates, and the exact Pearland ZIP code affect scheduling."),
  A("friendswood","Friendswood","South and southeast","Friendswood is an incorporated community southeast of Houston with wooded neighborhoods, Clear Creek corridors, and suburban commercial areas.","Older homes, custom properties, newer subdivisions, schools, offices, and local retail may have mature landscaping and varied utility ages.","Root intrusion, slab leaks, drainage access, flood-repair history, and long yard services should be evaluated without assuming a neighborhood-wide condition.","City jurisdiction, creek crossings, narrow residential streets, and routes from I-45 or FM 528 should be planned."),
  A("league-city","League City","South and southeast","League City extends across Galveston and Harris counties near Clear Lake, I-45, waterfront communities, and fast-growing suburban corridors.","Established neighborhoods, new master-planned developments, marina-area homes, apartments, medical facilities, and retail create multiple property profiles.","Waterfront exposure, slab systems, irrigation backflow, high-demand water heating, and utility district differences can change service requirements.","County, subdivision, gate, bridge or waterfront access, and I-45 traffic should be included in routing details."),
  A("clear-lake","Clear Lake","South and southeast","Clear Lake is a southeast Houston-area district shaped by the lake, NASA-related employment, marinas, planned neighborhoods, and commercial centers.","Waterfront homes, established subdivisions, apartments, offices, hotels, laboratories, and retail properties present residential and specialized commercial needs.","Salt-air exposure near the water, long hot-water runs, commercial backflow, slab piping, and remodel history may influence equipment and materials.","Identify the exact municipality or Houston jurisdiction, waterfront access, security, and routes near NASA Parkway and I-45."),
  A("webster","Webster","South and southeast","Webster is a compact city near I-45 and Clear Lake with a strong concentration of medical, hospitality, restaurant, retail, and apartment properties.","High-occupancy commercial buildings, multifamily communities, hotels, and limited single-family areas create intensive fixture and hot-water demand.","Commercial water heaters, grease waste, backflow assemblies, shared stacks, and scheduled shutdowns often shape the correct response.","Medical-campus access, loading areas, tenant coordination, and heavy traffic near Bay Area Boulevard should be planned."),
  A("alvin","Alvin","South and southeast","Alvin is a Brazoria County city south of Houston with an established town center, subdivisions, agricultural edges, and regional commercial growth.","Older homes, newer neighborhoods, acreage properties, schools, restaurants, and light industrial buildings may use municipal or private systems.","Well and septic interfaces outside serviced areas, long buried lines, older drains, and commercial grease handling require accurate property details.","County roads, rail crossings, acreage gates, city limits, and routes from SH 35 or nearby highways affect travel and equipment access."),
  A("manvel","Manvel","South and southeast","Manvel is a growing Brazoria County community along the SH 288 corridor where acreage properties and major new residential development meet.","Custom rural homes, wells and septic systems, new master-planned subdivisions, schools, and emerging commercial centers have distinct service infrastructure.","Private-system responsibility, long utility runs, new-build warranties, water treatment, and pressure regulation should be established before matching.","Construction traffic, subdivision phase, county roads, gates, and exact municipal or ETJ location are important dispatch facts."),
  A("pasadena","Pasadena","East Houston","Pasadena is an east-Harris County city with established neighborhoods, petrochemical-industry corridors, retail, institutions, and commercial districts.","Postwar homes, apartments, restaurants, schools, warehouses, offices, and industrial-support facilities create broad residential and commercial scopes.","Older drains, slab piping, commercial backflow, high-use fixtures, and industrial-site credentialing may require different providers.","SH 225 traffic, rail crossings, facility security, permit jurisdiction, and shift schedules should be considered."),
  A("deer-park","Deer Park","East Houston","Deer Park is an incorporated east-Harris County community near SH 225 with residential neighborhoods, schools, and industrial employment areas.","Single-family homes, apartments, local businesses, institutional buildings, and industrial-support properties span standard and specialized service needs.","Residential pipe repairs differ sharply from work involving controlled industrial sites, process boundaries, or specialized access requirements.","Facility badging, city jurisdiction, rail and SH 225 routes, and residential-versus-industrial location must be clear before dispatch."),
  A("la-porte","La Porte","East Houston","La Porte sits along Galveston Bay east of Houston with waterfront areas, established neighborhoods, port-related activity, and industrial corridors.","Homes, apartments, marinas, restaurants, schools, warehouses, and industrial facilities may face different material and access environments.","Coastal exposure, buried service corrosion, backflow, commercial drainage, and storm-repair history can inform—not replace—site diagnosis.","Bridge and port traffic, facility security, waterfront access, and emergency restrictions should be checked."),
  A("baytown","Baytown","East Houston","Baytown spans areas near the Houston Ship Channel, San Jacinto River, and Galveston Bay with residential, commercial, and industrial districts.","Established homes, newer subdivisions, apartments, hospitals, restaurants, retail, and industrial-support properties create varied plumbing systems.","City service boundaries, coastal conditions, slab piping, commercial backflow, and high-occupancy hot-water demand may influence the scope.","Ship Channel crossings, SH 146 and I-10 traffic, industrial security, and the exact side of the city are important routing details."),
  A("channelview","Channelview","East Houston","Channelview is an unincorporated east-Harris County community along I-10 and the Ship Channel corridor.","Established neighborhoods, apartments, truck and industrial businesses, restaurants, and semi-rural pockets may fall under different utility districts.","Septic or private-system edges, older buried piping, heavy commercial use, backflow, and jurisdictional boundaries need address-level verification.","I-10 traffic, rail crossings, industrial access rules, MUD identification, and unincorporated permitting context should be supplied."),
];

export const areaBySlug = Object.fromEntries(areas.map((area) => [area.slug, area]));
export const areaGroups = [...new Set(areas.map((area) => area.region))].map((label) => ({ label, slug: label.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/(^-|-$)/g,""), areas: areas.filter((area) => area.region === label) }));
